// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address user) public {
        vm.assume(user != address(0) && user != address(this) && user != address(c));
        vm.assume(amount1 < type(uint256).max / 2 && amount2 < type(uint256).max / 2);
        vm.deal(user, amount1 + amount2);

        vm.prank(user);
        c.addToBalance{value: amount1}();
        vm.prank(user);
        c.addToBalance{value: amount2}();

        assertTrue(c.getBalance(user) == amount1 + amount2);
    }
}
